lay:grid;grid-template-columns:repeat(auto-fill,minmax(270px,1fr));gap:13px}.site-card{cursor:pointer;background:#fbfdff;border:1px solid #dbe5ef;border-radius:7px;padding:15px;transition:border .18s,box-shadow .18s,transform .18s}.site-card:hover,.site-card.selected{border-color:#0b5ea8;box-shadow:0 8px 18px rgba(11,94,168,.12);transform:translateY(-1px)}.site-card-top{display:flex;justify-content:space-between;gap:10px}.site-name{font-weight:700;font-size:.95rem;color:#17324d}.site-url{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;max-width:190px;color:#64748b;font-size:.73rem;margin-top:3px}.status-badge{display:inline-block;padding:4px 7px;border-radius:3px;font-size:.7rem;font-weight:700}.status-badge.UP{background:#dcfce7;color:#166534}.status-badge.DOWN{background:#fee2e2;color:#991b1b}.status-badge.ERROR{background:#fef3c7;color:#92400e}.status-badge.PENDING{background:#e2e8f0;color:#475569}.site-metrics{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:13px}.m-label{font-size:.7rem;color:#64748b}.m-value{font-size:.92rem;font-weight:700;color:#17324d}.ping-strip{display:flex;gap:2px;margin-top:13px;height:18px}.ping-tick{flex:1;min-width:3px;border-radius:2px;background:#e2e8f0}.ping-tick.UP{background:#22c55e}.ping-tick.DOWN{background:#ef4444}.ping-tick.ERROR{background:#f6b322}.card-actions{display:flex;align-items:center;justify-content:space-between;margin-top:11px}.ghost{border:0;background:none;color:#dc2626;font-size:.76rem;padding:0}.dashboard-split{display:grid;grid-template-columns:minmax(0,1.25fr) minmax(340px,.75fr);gap:18px}.chart-wrap{height:270px;position:relative}.table-scroll{overflow:auto}.table-scroll table{width:100%;border-collapse:collapse;font-size:.82rem}.table-scroll th{text-align:left;padding:8px;border-bottom:1px solid #dbe5ef;color:#64748b;font-size:.72rem;text-transform:uppercase}.table-scroll td{padding:9px 8px;border-bottom:1px solid #edf2f7}.status-UP{color:#15803d;font-weight:700}.status-DOWN,.status-ERROR{color:#dc2626;font-weight:700}.empty-state{padding:26px;color:#64748b;border:1px dashed #cbd5e1;border-radius:6px;text-align:center}.toast{position:fixed;bottom:20px;left:50%;transform:translateX(-50%) translateY(20px);background:#17324d;color:#fff;padding:10px 18px;border-radius:6px;font-size:13px;opacity:0;pointer-events:none;transition:all .25s ease;z-index:1100}.toast.show{opacity:1;transform:translateX(-50%) translateY(0)}@media(max-width:900px){.summary-grid{grid-template-columns:repeat(2,1fr)}.dashboard-split{grid-template-columns:1fr}}@media(max-width:600px){.monitoring-head{flex-direction:column}.monitoring-actions{width:100%}.monitoring-actions .btn{flex:1}.add-form{grid-template-columns:1fr}.summary-grid{gap:9px}.stat-card{padding:13px}.stat-card .value{font-size:1.35rem}.monitor-panel{padding:14px}.site-grid{grid-template-columns:1fr}.chart-wrap{height:220px}}
