<div class="web-monitoring-page"><div class="monitoring-head"><div><div class="monitoring-eyebrow">Web Monitoring</div><h1>Ringkasan Kesehatan Layanan</h1><p>Status ketersediaan dan performa endpoint yang dipantau.</p></div><div class="monitoring-actions"><a href="{{ route('web-monitoring-checklists.index') }}" class="btn btn-outline-primary">Checklist Web</a><button id="refreshBtn" class="btn btn-brand" type="button" onclick="refreshNow()">Cek Sekarang</button></div></div><div class="summary-grid"><div class="stat-card"><div class="label">Total Situs</div><div class="value" id="statTotal">0</div><div class="hint">Endpoint terdaftar</div></div><div class="stat-card up"><div class="label">Layanan Normal</div><div class="value" id="statUp">0</div><div class="hint">Status terakhir UP</div></div><div class="stat-card down"><div class="label">Perlu Perhatian</div><div class="value" id="statDown">0</div><div class="hint">DOWN atau ERROR</div></div><div class="stat-card response"><div class="label">Rata-rata Respons</div><div class="value" id="statAvg">-</div><div class="hint">Pemeriksaan terakhir</div></div></div><div class="monitor-panel"><div class="panel-head"><div><h2>Tambah Situs Dipantau</h2><div class="panel-subtitle">Masukkan endpoint HTTP atau HTTPS untuk dipantau.</div></div></div><form class="add-form" onsubmit="handleAddSite(event)"><input type="text" id="siteName" placeholder="Nama situs"><input type="text" id="siteUrl" placeholder="https://contoh.com" required><button type="submit" class="primary">+ Tambah</button></form></div><div class="monitor-panel"><div class="panel-head"><div><h2>Status Situs</h2><div class="panel-subtitle">Pilih kartu situs untuk melihat tren respons.</div></div><span id="siteCountLabel" class="panel-subtitle"></span></div><div id="siteGrid" class="site-grid"></div></div><div class="dashboard-split"><div class="monitor-panel"><div class="panel-head"><div><h2>Tren Response Time</h2><div class="panel-subtitle" id="chartSiteLabel">Pilih situs di atas</div></div><span class="live-indicator">Live</span></div><div class="chart-wrap"><canvas id="rtChart"></canvas></div></div><div class="monitor-panel"><div class="panel-head"><div><h2>Log Terbaru</h2><div class="panel-subtitle">30 pemeriksaan terakhir</div></div></div><div class="table-scroll"><table><thead><tr><th>Waktu</th><th>Situs</th><th>Kode</th><th>Response</th><th>Status</th></tr></thead><tbody id="logsBody"></tbody></table></div></div></div></div><div class="toast" id="toast"></div>
<script>
const CSRF_TOKEN=document.querySelector('meta[name="csrf-token"]').content;let currentData=null,selectedSiteId=null;const fmtTime=ts=>new Date(ts).toLocaleTimeString('id-ID',{hour:'2-digit',minute:'2-digit',second:'2-digit'});const fmtDateTime=ts=>new Date(ts).toLocaleString('id-ID',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'});function showToast(msg){const t=document.getElementById('toast');t.textContent=msg;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2400)}async function jsonFetch(url,options={}){const res=await fetch(url,{headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':CSRF_TOKEN},...options});if(!res.ok){const body=await res.json().catch(()=>({}));throw new Error(body.message||('HTTP '+res.status))}return res.json()}function loadDashboard(){jsonFetch('{{ route('dashboard.data') }}').then(renderAll).catch(onError)}function refreshNow(){const btn=document.getElementById('refreshBtn');btn.disabled=true;btn.textContent='Mengecek...';jsonFetch('{{ route('dashboard.check-now') }}',{method:'POST'}).then(data=>{renderAll(data);showToast('Pengecekan selesai')}).catch(onError).finally(()=>{btn.disabled=false;btn.textContent='Cek Sekarang'})}function onError(err){showToast('Error: '+err.message);console.error(err)}function handleAddSite(e){e.preventDefault();const name=document.getElementById('siteName').value.trim(),url=document.getElementById('siteUrl').value.trim();if(!url)return;jsonFetch('{{ route('sites.store') }}',{method:'POST',body:JSON.stringify({name,url})}).then(()=>{document.getElementById('siteName').value='';document.getElementById('siteUrl').value='';showToast('Situs ditambahkan');loadDashboard()}).catch(onError)}function deleteSite(id,evt){evt.stopPropagation();if(!confirm('Hapus situs ini dari pemantauan?'))return;jsonFetch('/sites/'+id,{method:'DELETE'}).then(()=>{showToast('Situs dihapus');loadDashboard()}).catch(onError)}function renderAll(data){currentData=data;document.getElementById('statTotal').textContent=data.summary.totalSites;document.getElementById('statUp').textContent=data.summary.upSites;document.getElementById('statDown').textContent=data.summary.downSites;document.getElementById('statAvg').textContent=data.summary.avgResponse?data.summary.avgResponse+' ms':'-';document.getElementById('siteCountLabel').textContent=data.sites.length+' situs';renderSiteGrid(data.sites);renderLogs(data.recentLogs);if(!selectedSiteId&&data.sites.length)selectedSiteId=data.sites[0].id;renderChart()}function renderSiteGrid(sites){const grid=document.getElementById('siteGrid');if(!sites.length){grid.innerHTML='<div class="empty-state">Belum ada situs. Tambahkan URL di atas untuk mulai memantau.</div>';return}grid.innerHTML=sites.map(site=>{const status=site.lastStatus||'PENDING',ticks=site.history.length?site.history.map(h=>'<div class="ping-tick '+h.status+'"></div>').join(''):'<div style="font-size:10px;color:#8493A6;">belum ada riwayat</div>',rt=site.lastResponseMs?site.lastResponseMs+' ms':'-',up=site.uptimePct!=null?site.uptimePct+'%':'-';return '<div class="site-card '+(site.id===selectedSiteId?'selected':'')+'" onclick="selectSite('+site.id+')"><div class="site-card-top"><div><div class="site-name">'+escapeHtml(site.name)+'</div><div class="site-url">'+escapeHtml(site.url)+'</div></div><span class="status-badge '+status+'">'+status+'</span></div><div class="site-metrics"><div><div class="m-label">Response</div><div class="m-value">'+rt+'</div></div><div><div class="m-label">Uptime</div><div class="m-value">'+up+'</div></div></div><div class="ping-strip">'+ticks+'</div><div class="card-actions"><span style="font-size:10px;color:#8493A6;">'+(site.active?'aktif':'nonaktif')+'</span><button class="ghost" onclick="deleteSite('+site.id+',event)">Hapus</button></div></div>'}).join('')}function selectSite(id){selectedSiteId=id;renderSiteGrid(currentData.sites);renderChart()}function renderChart(){const site=(currentData.sites||[]).find(s=>s.id===selectedSiteId),canvas=document.getElementById('rtChart'),label=document.getElementById('chartSiteLabel');if(!canvas)return;const bounds=canvas.parentElement.getBoundingClientRect(),ratio=window.devicePixelRatio||1;canvas.width=Math.max(1,Math.floor(bounds.width*ratio));canvas.height=Math.max(1,Math.floor(bounds.height*ratio));canvas.style.width=bounds.width+'px';canvas.style.height=bounds.height+'px';const ctx=canvas.getContext('2d');ctx.scale(ratio,ratio);const width=bounds.width,height=bounds.height;ctx.clearRect(0,0,width,height);if(!site||!site.history.length){label.textContent=site?site.name+' - belum ada data respons':'Pilih situs di atas';return}const points=site.history.filter(h=>Number.isFinite(Number(h.ms)));if(!points.length)return;label.textContent=site.name;const pad={top:20,right:16,bottom:30,left:48},graphW=width-pad.left-pad.right,graphH=height-pad.top-pad.bottom,max=Math.max(...points.map(p=>Number(p.ms)),1),roundedMax=Math.ceil(max/100)*100||100;ctx.font='11px sans-serif';ctx.fillStyle='#64748b';ctx.textAlign='right';for(let step=0;step<=4;step++){const value=roundedMax-(roundedMax*step/4),y=pad.top+(graphH*step/4);ctx.strokeStyle='#e2e8f0';ctx.beginPath();ctx.moveTo(pad.left,y);ctx.lineTo(width-pad.right,y);ctx.stroke();ctx.fillText(Math.round(value)+' ms',pad.left-7,y+4)}const xFor=i=>pad.left+(points.length===1?graphW/2:i*graphW/(points.length-1)),yFor=v=>pad.top+graphH-(Number(v)/roundedMax*graphH);ctx.beginPath();points.forEach((p,i)=>i?ctx.lineTo(xFor(i),yFor(p.ms)):ctx.moveTo(xFor(i),yFor(p.ms)));ctx.strokeStyle='#0b5ea8';ctx.lineWidth=2.5;ctx.stroke();points.forEach((p,i)=>{ctx.beginPath();ctx.arc(xFor(i),yFor(p.ms),3.5,0,Math.PI*2);ctx.fillStyle=p.status==='UP'?'#0b5ea8':'#dc2626';ctx.fill()});ctx.fillStyle='#64748b';ctx.textAlign='left';ctx.font='10px sans-serif';ctx.fillText(fmtTime(points[0].t),pad.left,height-9);ctx.textAlign='right';ctx.fillText(fmtTime(points[points.length-1].t),width-pad.right,height-9)}function renderLogs(logs){const body=document.getElementById('logsBody');body.innerHTML=logs.length?logs.map(l=>'<tr><td>'+fmtDateTime(l.t)+'</td><td>'+escapeHtml(l.name)+'</td><td>'+(l.code||'-')+'</td><td>'+l.ms+' ms</td><td class="status-'+l.status+'">'+l.status+'</td></tr>').join(''):'<tr><td colspan="5">Belum ada log.</td></tr>'}function escapeHtml(str){const div=document.createElement('div');div.textContent=str||'';return div.innerHTML}window.addEventListener('resize',()=>{if(currentData)renderChart()});loadDashboard();setInterval(loadDashboard,15000);
</script>
